data.code:
example_multiple_formats
{
  UNCOMPRESSED {
    field_1;  //  4 bits
    field_2;  //  4 bits
    field_3;  // 24 bits
  }

  DEFAULT {
    field_1 =:= static;
    field_2 =:= uncompressed_value(4, 2);
    field_3 =:= lsb(4, 0);
  }

  COMPRESSED format0 {
    discriminator =:= '0'; // 1 bit
    field_3;               // 4 bits
  }

  COMPRESSED format1 {
    discriminator =:= '1';           //  1 bit
    field_1       =:= irregular(4);  //  4 bits
    field_3       =:= irregular(24); // 24 bits
  }
}
